import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

// Transport-independent frame decoder for a bounded SSE-like protocol.
// Bytes are decoded as strict UTF-8 across pushes, split into lines at LF/CRLF,
// and assembled into {event,data} frames dispatched at blank lines.
export function createDecoder(){
  const utf8=new TextDecoder('utf-8',{fatal:true,ignoreBOM:false});
  let text='';            // decoded characters not yet forming a complete line
  let dataLines=null;     // array of data values for the current frame, or null
  let eventName='';       // last event-field value in the current frame
  let terminated=false;   // a [DONE] frame has been seen
  let finished=false;     // finish() succeeded
  let poisoned=false;     // a push/finish was rejected

  const fail=(message)=>{poisoned=true;throw new Error(message);};

  function handleLine(line,frames){
    if(line.endsWith('\r'))line=line.slice(0,-1);
    if(line===''){
      if(dataLines!==null){
        const data=dataLines.join('\n');
        if(terminated)fail('data after termination marker');
        if(data==='[DONE]')terminated=true;
        else frames.push({event:eventName===''?'message':eventName,data});
      }
      dataLines=null;eventName='';
      return;
    }
    if(terminated)fail('nonblank line after termination marker');
    if(line.startsWith(':'))return;
    const colon=line.indexOf(':');
    let name=line,value='';
    if(colon!==-1){
      name=line.slice(0,colon);
      value=line.slice(colon+1);
      if(value.startsWith(' '))value=value.slice(1);
    }
    if(name==='data'){(dataLines??=[]).push(value);}
    else if(name==='event'){eventName=value;}
  }

  function consume(decoded,frames){
    text+=decoded;
    let start=0,index;
    while((index=text.indexOf('\n',start))!==-1){
      handleLine(text.slice(start,index),frames);
      start=index+1;
    }
    text=text.slice(start);
  }

  return {
    push(chunk){
      if(poisoned)fail('decoder is poisoned');
      if(finished)fail('push after finish');
      if(!(chunk instanceof Uint8Array))fail('chunk must be a Uint8Array');
      let decoded;
      try{decoded=utf8.decode(chunk,{stream:true});}
      catch(error){fail('invalid UTF-8: '+error.message);}
      const frames=[];
      consume(decoded,frames);
      return frames;
    },
    finish(){
      if(poisoned)fail('decoder is poisoned');
      if(finished)fail('finish called twice');
      let decoded;
      try{decoded=utf8.decode();}
      catch(error){fail('invalid UTF-8: '+error.message);}
      consume(decoded,[]);
      if(text!=='')fail('unterminated final line');
      if(dataLines!==null||eventName!=='')fail('pending frame fields at finish');
      if(!terminated)fail('stream ended without termination marker');
      finished=true;
      return [];
    },
  };
}

const BASE64=/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/;
function decodeBase64(encoded,index){
  if(typeof encoded!=='string')throw new Error(`chunks[${index}] is not a string`);
  if(!BASE64.test(encoded))throw new Error(`chunks[${index}] is not canonical base64`);
  const bytes=Buffer.from(encoded,'base64');
  if(bytes.toString('base64')!==encoded)throw new Error(`chunks[${index}] has noncanonical padding bits`);
  return bytes;
}

export function runCli(argv){
  if(argv.length!==1)throw new Error('usage: stream-framer.js INPUT_JSON_FILE');
  const input=JSON.parse(fs.readFileSync(argv[0],'utf8'));
  if(typeof input!=='object'||input===null||Array.isArray(input))throw new Error('input must be a JSON object');
  if(!Array.isArray(input.chunks))throw new Error('input.chunks must be an array');
  const chunks=input.chunks.map(decodeBase64);
  const decoder=createDecoder(),frames=[];
  for(const chunk of chunks)frames.push(...decoder.push(chunk));
  frames.push(...decoder.finish());
  return JSON.stringify({frames})+'\n';
}

function isMain(){
  const entry=process.argv[1];
  if(!entry)return false;
  const self=fileURLToPath(import.meta.url);
  try{return fs.realpathSync(path.resolve(entry))===fs.realpathSync(self);}
  catch{return path.resolve(entry)===self;}
}

if(isMain()){
  let output;
  try{output=runCli(process.argv.slice(2));}
  catch(error){
    process.stderr.write(String(error&&error.message||error)+'\n');
    process.exitCode=2;
  }
  if(output!==undefined)process.stdout.write(output);
}
