import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createDecoder} from '../stream-framer.js';

const SCRIPT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'../stream-framer.js');
const b=(s)=>Buffer.from(s);
function decodeAll(text,size){
  const d=createDecoder(),frames=[],bytes=Buffer.from(text);
  for(let i=0;i<bytes.length;i+=size)frames.push(...d.push(bytes.subarray(i,i+size)));
  d.finish();return frames;
}

test('same frames at every chunk size',()=>{
  const text='﻿: comment\r\nevent: a\r\ndata: x\r\ndata:\r\nfoo: bar\r\n\r\n﻿data: y\n\nevent: z\n\ndata: [DONE]\n\n';
  // The second BOM is ordinary data, so "﻿data" is an unknown field name.
  const expected=[{event:'a',data:'x\n'}];
  for(const size of [1,2,3,5,7,1000])assert.deepEqual(decodeAll(text,size),expected,`size ${size}`);
});

test('CR handling: lone CR is data, CR before LF stripped even across chunks',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(b('data: a\rb\r')),[]);
  assert.deepEqual(d.push(b('\n\r')),[]);
  assert.deepEqual(d.push(b('\ndata: [DONE]\n\n')),[{event:'message',data:'a\rb'}]);
  assert.deepEqual(d.finish(),[]);
});

test('field parsing: leading space, no colon, case-sensitivity, event leak',()=>{
  const d=createDecoder();
  const frames=d.push(b('data:  two spaces\ndata\nData: ignored\nevent: e1\nevent\n\nevent: leak\n\ndata: after\n\ndata: [DONE]\n\n'));
  assert.deepEqual(frames,[{event:'message',data:' two spaces\n'},{event:'message',data:'after'}]);
  d.finish();
});

test('event without data does not dispatch or leak',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(b('event: x\n\ndata: y\n\ndata: [DONE]\n\n')),[{event:'message',data:'y'}]);
  d.finish();
});

test('[DONE] with an event name still terminates; data lines after it throw',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(b('event: end\ndata: [DONE]\n\n\n\n')),[]);
  assert.throws(()=>d.push(b('data: x\n')),Error);
  assert.throws(()=>d.push(new Uint8Array()),Error);
  assert.throws(()=>d.finish(),Error);
});

test('after termination: comments, unknown fields, second marker throw',()=>{
  for(const tail of [': c\n','foo\n','data: [DONE]\n\n','\r\n\r\nx\n']){
    const d=createDecoder();d.push(b('data: [DONE]\n\n'));
    assert.throws(()=>d.push(b(tail)),Error,tail);
  }
});

test('multi-line [DONE] is not a marker; split [DONE] across data is data',()=>{
  const d=createDecoder();
  assert.deepEqual(d.push(b('data: [DONE]\ndata:\n\ndata: [DO\ndata: NE]\n\ndata: [DONE]\n\n')),[
    {event:'message',data:'[DONE]\n'},{event:'message',data:'[DO\nNE]'}]);
  d.finish();
});

