  assert.throws(()=>d.push(b('data: late\n')),Error);
});

test('invalid UTF-8 throws and poisons; incomplete sequence at finish throws',()=>{
  const d=createDecoder();
  assert.throws(()=>d.push(Uint8Array.of(0xff)),Error);
  assert.throws(()=>d.push(b('')),Error);
  assert.throws(()=>d.finish(),Error);
  const e=createDecoder();e.push(b('data: [DONE]\n\n'));e.push(Uint8Array.of(0xe9));
  assert.throws(()=>e.finish(),Error);
  const f=createDecoder();f.push(b('data: [DONE]\n\n'));
  assert.throws(()=>f.push(Uint8Array.of(0xed,0xa0,0x80)),Error); // surrogate
  const g=createDecoder();
  assert.throws(()=>g.push(Uint8Array.of(0xc0,0x80)),Error); // overlong
