  d.push(Uint8Array.of(0xef));d.push(Uint8Array.of(0xbb));
  assert.deepEqual(d.push(Buffer.concat([Uint8Array.of(0xbf),b('data: a\n\ndata: ﻿\n\ndata: [DONE]\n\n')])),[
    {event:'message',data:'a'},{event:'message',data:'﻿'}]);
  d.finish();
});

