  const cases=[
    '[]','null','"x"','{"chunks":null}','{"chunks":[1]}','{"chunks":["YQ"]}','{"chunks":["YQ==="]}',
    '{"chunks":["YR=="]}','{"chunks":["YQ== "]}','{"chunks":["-_=="]}','{"chunks":["YQ==\\n"]}',
    '{"chunks":["'+enc('data: x\n\n')+'"]}','{"chunks":["'+enc('data: [DONE]\n\nx\n')+'"]}','{"chunks":["/w=="]}','not json',
  ];
  for(const content of cases){
    const r=withFixture(content,(file)=>runCli([file]));
    assert.equal(r.status,2,content);assert.equal(r.stdout,'',content);assert.notEqual(r.stderr,'',content);
  }
  for(const args of [[],['a','b'],[path.join(os.tmpdir(),'framer-does-not-exist.json')]]){
    const r=runCli(args);assert.equal(r.status,2);assert.equal(r.stdout,'');assert.notEqual(r.stderr,'');
  }
});

test('importing the module does not run the CLI',()=>{
  const r=spawnSync(process.execPath,['--input-type=module','-e',`import ${JSON.stringify('file://'+SCRIPT)};console.log('ok')`],{encoding:'utf8'});
  assert.equal(r.status,0);assert.equal(r.stdout,'ok\n');assert.equal(r.stderr,'');
});

